\label{thm:main}
For every $\pi$ with $W(\pi)<\infty$, and every $0<C\le1$,
\begin{equation}\label{eq:main}
\theta(C)\;\ge\;\theta^{\rightarrow}(C)\;\ge\;1-W(\pi)\sum_{r\ge1}\pi(r)^2\Bigl(\frac1{p_r}-1\Bigr).
\end{equation}
In particular $C_c\leC_c^{\rightarrow}\le C$ whenever the right-hand side is positive.

\label{lem:sibuya}
For $0<\alpha<1$:
\begin{itemize}
\item[(S1)] $\displaystyle\pi_\alpha(r)=\frac{\alpha}{r}\prod_{k=1}^{r-1}\Bigl(1-\frac{\alpha}{k}\Bigr)>0$, and
$\sum_{r\ge1}\pi_\alpha(r)=1$.
\item[(S2)] $\pi_\alpha(r)\le\alpha\,r^{-1-\alpha}$.
\item[(S3)] The renewal sequence is $\displaystyle u(x)=\frac{\Gamma(x+\alpha)}{\Gamma(\alpha)\,x!}$.
\item[(S4)] For $0<\alpha<\frac12$,
\begin{equation}\label{eq:Wsib}
W(\alpha):=W(\pi_\alpha)=\frac{\Gamma(1-2\alpha)}{\Gamma(1-\alpha)^2},\qquad
\sum_{r\ge1}\pi_\alpha(r)^2=\frac{\Gamma(1+2\alpha)}{\Gamma(1+\alpha)^2}-1,
\end{equation}
and $W(\alpha)=\infty$ for $\alpha\ge\frac12$.
\end{itemize}

\label{cor:bound}
For $0<\sigma<1$,
\begin{equation}\label{eq:CU}
C_c(\sigma)\;\le\;C_c^{\rightarrow}(\sigma)\;\le\;C^U(\sigma):=\min_{\sigma/2<\alpha<1/2}\;
\frac{\displaystyle\sum_{r\ge1}\pi_\alpha(r)^2\,r^{1+\sigma}}
{\displaystyle\frac{\Gamma(1-\alpha)^2}{\Gamma(1-2\alpha)}+\frac{\Gamma(1+2\alpha)}{\Gamma(1+\alpha)^2}-1}.
\end{equation}
Moreover, the numerator is at most $\alpha^2\zeta(1+2\alpha-\sigma)$, which gives the closed form
\begin{equation}\label{eq:Ccf}
C^U(\sigma)\;\le\;C^{\rm cf}(\sigma):=\min_{\sigma/2<\alpha<1/2}\;
\frac{\alpha^2\,\zeta(1+2\alpha-\sigma)}
{\displaystyle\frac{\Gamma(1-\alpha)^2}{\Gamma(1-2\alpha)}+\frac{\Gamma(1+2\alpha)}{\Gamma(1+\alpha)^2}-1},
\end{equation}
and, for $0<\sigma<\tfrac12$,
\begin{equation}\label{eq:simple}
C^{\rm cf}(\sigma)\;\le\;\sigma^2\,\zeta(1+\sigma)\,\frac{\Gamma(1-2\sigma)}{\Gamma(1-\sigma)^2}
\;=\;\sigma+\gamma_E\,\sigma^2+O(\sigma^3),
\end{equation}
where $\gamma_E=0.577\ldots$ is Euler's constant. Consequently, as $\sigma\to0$,
\begin{equation}\label{eq:asym}
\begin{aligned}
1\;&\le\;\zeta(1+\sigma)\,C_c^{\rightarrow}(\sigma)\;\le\;1+2\gamma_E\,\sigma+O(\sigma^2),\\[2pt]
\tfrac12\;&\le\;\zeta(1+\sigma)\,C_c(\sigma)\;\le\;1+2\gamma_E\,\sigma+O(\sigma^2).
\end{aligned}
\end{equation}

\label{thm:block}
For all $L\ge1$, all $\pi$ with $W(\pi)<\infty$ and all $0<C\le1$,
\begin{equation}\label{eq:block}
\theta(C)\ge 1-W(\pi)\Bigl[(1-g_L)+\sum_{r\ge1}\pi(r)^2\Bigl(\frac{1}{p^{(L)}_r}-1\Bigr)\Bigr].
\end{equation}

\label{lem:ingredients}
Let $D_r=\sum_{x\in B_0,\,y\in B_r}(y-x)^{-1-\sigma}$, so that $C\,D_r$ is the mean number of open bonds between two
blocks at distance $r$. Then:
\begin{itemize}
\item[(B1)] $g_L\ge C^{L-1}$, and also
$g_L\ge\prod_{t=1}^{L-1}\bigl[1-\prod_{j=1}^{t}(1-p_j)\bigr]$.
\item[(B2)] $D_r\ge L^{1-\sigma}\,r^{-1-\sigma}$.
\item[(B3)] $\displaystyle\frac{1}{p^{(L)}_r}-1\le\frac{1}{e^{CD_r}-1}\le\frac{1}{C\,D_r}\le\frac{r^{1+\sigma}}{C\,L^{1-\sigma}}$.
\end{itemize}
